import type { Scenario, Scene } from '../types';
import { inventoryClass } from '../items';
import { largeAdventure, largeEnd, largeScene, largeTags } from './largeContentTools';

type BeatChoice = { id: string; label: string; result: string; requiresItem?: string };
type RoadStory = {
  id: string; title: string; subtitle: string; risk: 'LOW' | 'MODERATE' | 'HIGH' | 'SEVERE';
  setting: string; activity: string; hook: string; startTitle: string; start: string;
  approaches: [BeatChoice, BeatChoice, BeatChoice];
  threatTitle: string; threat: string; responses: [BeatChoice, BeatChoice, BeatChoice];
  aftermathTitle: string; aftermath: string; endings: [{ id: string; label: string; result: string }, { id: string; label: string; result: string }];
  rewardText: string; gear?: string; gearName?: string; provenance?: string; coins: number; lesson: string; lore?: string;
  combat?: { enemy: string; winChance: number; damage: number; win: string; loss: string };
};

const s = (id: string, title: string, text: string, choices: Scene['choices'], tone: Scene['tone'] = 'safe', textVariants?: Scene['textVariants']): Scene => ({ id, title, text, choices, tone, ...(textVariants ? { textVariants } : {}) });
const e = (id: string, title: string, text: string) => largeEnd(id, title, text);

const stories: RoadStory[] = [
  { id:'the-glass-at-milepost-nine', title:'The Glass at Milepost Nine', subtitle:'A dropped lantern and fresh wheel cuts suggest a road crew is being watched.', risk:'MODERATE', setting:'wooded stage road', activity:'investigation/mystery', hook:'A traveler spots a lookout’s field glass before a wagon reaches a blind bend.', startTitle:'A Glint in the Brush', start:'From the rise you see a brass flash in the brush above the stage road. Below, a freight wagon is approaching a narrow turn. No one has signaled the driver, and the brush has a clear retreat path into the trees.', approaches:[{id:'watch',label:'Use your Field Glasses to watch the brush from the rise',result:'A person lowers a pair of field glasses and signals toward the bend; you have seen a lookout, not the whole crew.',requiresItem:'fieldGlasses'},{id:'warn',label:'Signal the wagon to stop before the bend',result:'The driver stops on the open stretch and sees the same glint from the brush.'},{id:'circle',label:'Take the open ditch around the back of the rise',result:'You find fresh boot marks leading away from the road, but do not approach the hidden person.'}], threatTitle:'The Wagon Has Stopped', threat:'A second figure steps onto the road and asks the driver for the strongbox. The lookout is still above you. The wagon is stopped in the open; the trees offer cover, and the driver can reverse toward the toll station.', responses:[{id:'signalStation',label:'Use the whistle to call the toll station',result:'The station answers and the road crew withdraws before reaching the wagon.'},{id:'coverDriver',label:'Keep the driver behind the wheel and offer a clear retreat',result:'The lookout leaves first; the second figure follows without taking the strongbox.'},{id:'recordFace',label:'Keep distance and remember their clothing',result:'You preserve a useful description while the driver backs toward the staffed road.'}], aftermathTitle:'A Pair of Field Glasses', aftermath:'The road is clear. A survey assistant returning from the toll station identifies the brass instrument as a field-glass case abandoned by the lookout, who left it when the station answered.', endings:[{id:'returnCase',label:'Leave the case with the assistant for its owner',result:'The case is logged as recovered property; the assistant will ask the road crew to identify its owner.'},{id:'stayForStatement',label:'Give the station a careful account before leaving',result:'The station records only what you witnessed: a lookout, a demand, and the direction of retreat.'}], rewardText:'The assistant later confirms the lookout surrendered the glasses as part of a restitution agreement. They are released to you with the owner’s consent.', gear:'fieldGlasses',gearName:'Field Glasses',provenance:'The former lookout relinquishes the glasses in a witnessed restitution agreement; they are not taken from an unconscious person.', coins:2, lesson:'A lookout’s signal can reveal coordination, but it does not tell you how many people are hidden nearby.', lore:'The milepost once marked the last place a stage could turn around before the old cut.' },
  { id:'the-screw-jack-road', title:'The Screw Jack Road', subtitle:'A wheel is being removed from a stranded wagon while its owner is held at a distance.', risk:'HIGH', setting:'prairie wagon road', activity:'rescue/care', hook:'A traveler must distinguish a roadside repair from a deliberate wagon theft.', startTitle:'The Wagon on Its Axle', start:'A wagon sits tilted beside a shallow ditch. Its driver, Ada Wynn, is standing well back with both hands visible. A stranger is working beneath the rear axle with a screw jack; a second horse is already turned toward the open prairie.', approaches:[{id:'callDriver',label:'Ask the driver what she saw before approaching',result:'Wynn says the pair offered help, then took the wheel when she refused to leave the wagon.'},{id:'coverHorse',label:'Move to the road side where the loose horse cannot bolt',result:'The horse settles, but the stranger under the axle now knows you are present.'},{id:'signal',label:'Call toward the nearest farm before closing the distance',result:'A farmhand answers from the ridge; the two strangers look toward the sound.'}], threatTitle:'They See You', threat:'The stranger under the wagon slides out holding a wrench. The second person has one hand on the horse’s bridle. The road behind you is open; the farmhand is still coming.', responses:[{id:'offerExit',label:'Offer them a clear way to leave without the wheel',result:'They back away from the wagon and ride off without the wheel.'},{id:'keepHorse',label:'Keep the horse between the driver and the strangers',result:'Wynn reaches the road while the strangers leave the wheel beside the axle.'},{id:'callFarm',label:'Hold position until the farmhand reaches the road',result:'The farmhand arrives with a dog and the strangers abandon their tools.'}], aftermathTitle:'A Wheel Back on the Ground', aftermath:'The owner confirms the wagon is hers and the screw jack belonged to the thieves. The axle is stable on level ground; the wheel can be refitted after the loose hardware is checked.', endings:[{id:'helpRefit',label:'Help Wynn refit the wheel before she travels',result:'Wynn reaches the farm at a walk and will have the smith inspect the axle.'},{id:'leaveForSmith',label:'Walk with Wynn to fetch the smith',result:'The wagon stays secured by the road, and Wynn will not risk another mile on hurried work.'}], rewardText:'Wynn gives you the compact jack the thieves left behind; the sheriff records it as abandoned property after she identifies her own tools.', gear:'foldingCarriageJack',gearName:'Folding Carriage Jack',provenance:'The wagon owner identifies the thieves’ abandoned jack and explicitly releases it after the sheriff records it.', coins:3, lesson:'A jack can lift an axle on firm, level ground; it cannot make a damaged hub sound.', combat:{enemy:'wagon thieves',winChance:.58,damage:4,win:'The thieves retreat when the farmhand arrives; Wynn stays clear until the axle is checked.',loss:'You take a hard blow while keeping the horse from bolting. The thieves leave the wheel, and the farmhand reaches Wynn.'} },
  { id:'the-paper-road', title:'The Paper Road', subtitle:'A county courier is forced to surrender a sealed map case at a fork.', risk:'MODERATE', setting:'county road fork', activity:'communication/witness', hook:'A courier’s route papers matter more than the case they travel in.', startTitle:'The Wrong Direction', start:'Courier Lenora Pike reaches a fork on foot, shaken but unhurt. Two riders demanded her sealed case, then rode west with it. She remembers one horse had a torn saddle flap; the county office is east, and the west road leads toward an abandoned toll shed.', approaches:[{id:'eastOffice',label:'Send Pike east to report the theft',result:'Pike leaves for the office while you preserve the fork as a witness point.'},{id:'checkTracks',label:'Compare the two sets of hoofprints first',result:'The westbound pair slowed at the fork, but the prints cannot show what is inside the case.'},{id:'seekWitness',label:'Ask the nearby farm for a witness before following',result:'A farmer saw the riders turn west and agrees to meet you at the fork.'}], threatTitle:'A Case Is Not Its Contents', threat:'At the toll shed, one rider waits with the case. The second is out of sight. The rider says the papers prove the road belongs to his family; a date seal and county ribbon remain visible on the latch.', responses:[{id:'askSeal',label:'Ask the rider to read the county date seal aloud',result:'He cannot name the issuing office and lowers the case.'},{id:'offerWitness',label:'Call the farmer to witness the handover',result:'The farmer arrives; the rider recognizes that the case can be traced and leaves it on the bench.'},{id:'stayBack',label:'Keep outside and ask Pike to identify the seal',result:'Pike confirms the county stamp from the road; the rider leaves before you close in.'}], aftermathTitle:'The Papers Stay Sealed', aftermath:'Pike checks the ribbon and confirms the county case is intact. The map inside has not been examined; the office will document whether any paper is missing.', endings:[{id:'returnCase',label:'Return the case sealed to Pike',result:'Pike takes it to the county clerk without opening it on the road.'},{id:'walkTogether',label:'Escort Pike to the office before the papers are checked',result:'The courier and case reach the office together, with the seal recorded at arrival.'}], rewardText:'The county clerk later releases the duplicate Lockable Map Case to you; the stolen case and original maps remain county property.', gear:'lockableMapCase',gearName:'Lockable Map Case',provenance:'The county transfers a documented spare case after the original is returned sealed.', coins:2, lesson:'A seal and a witness establish custody better than a stranger’s claim about what a paper says.', lore:'The toll shed was closed when the county road shifted to the east fork.' },
  { id:'the-stones-in-the-rut', title:'The Stones in the Rut', subtitle:'A farmer finds rocks placed where a wagon must slow beside a narrow bank.', risk:'HIGH', setting:'wooded road and ditch', activity:'travel/exploration', hook:'A prepared obstruction can be found and dismantled before the robbers arrive.', startTitle:'A Road Made Narrow', start:'A line of stones has been set across the wheel track at a wooded pinch point. One stone is tied to a thin cord disappearing into brush. No wagon has reached the bend yet; a dry ditch and a fence line give you two ways back.', approaches:[{id:'inspectCord',label:'Inspect the cord from the road edge',result:'The cord runs to a loose branch, not a trigger; it may be intended as a signal.'},{id:'warnFarm',label:'Warn the farmstead before touching the obstruction',result:'The farmer confirms a milk wagon is due and sends a boy to hold it back.'},{id:'moveStones',label:'Move only the loose stones from the wheel track',result:'The road opens slowly; fresh bootprints show someone has been working from the brush.'}], threatTitle:'A Signal, Not a Snare', threat:'A lookout whistles from the slope. Two people step from the brush and demand the farmer’s cash box. Their only cover is a fence corner; the ditch gives the wagon a clear retreat line.', responses:[{id:'useWhistle',label:'Answer with your Conductor’s Whistle',result:'The sharp signal brings a farmhand from the lower field; the pair withdraw before approaching the wagon.',requiresItem:'conductorWhistle'},{id:'openDitch',label:'Wave the wagon back through the open ditch',result:'The farmer turns the team while you keep the robbers at a distance.'},{id:'nameWitness',label:'Call out that the road is watched from the farmhouse',result:'The robbers leave the cash box and retreat toward the trees.'}], aftermathTitle:'The Road Opens Again', aftermath:'The obstruction is cleared and the farmer confirms nothing was taken. The cord was a lookout signal; no evidence shows what the robbers intended to do if a wagon stopped.', endings:[{id:'markPinch',label:'Mark the narrow stretch for the next wagon',result:'The farmer posts a warning at both approaches and waits for daylight before reopening the road.'},{id:'walkFarm',label:'Walk back with the farmer and give a statement',result:'The farmstead records the signal and the demand without claiming anyone was injured.'}], rewardText:'The farmer gives you the spare Conductor’s Whistle from the milk-wagon kit; the working signal stays with the team.', gear:'conductorWhistle',gearName:'Conductor’s Whistle',provenance:'The farmer releases a separately owned spare whistle after the road is made safe.', coins:1, lesson:'A cord across a road may be a lookout signal rather than a mechanical trap; inspect before pulling it.', combat:{enemy:'road extortionists',winChance:.51,damage:5,win:'The pair retreat toward the trees when the farmhands answer your call.',loss:'You are hurt in the scramble back to the ditch; the farmer and team reach the farmhouse.'} },
  { id:'the-ledger-under-canvas', title:'The Ledger Under Canvas', subtitle:'A freight clerk is missing after a night theft, but the wagon and its cargo remain.', risk:'LOW', setting:'freight platform and wagon yard', activity:'investigation/mystery', hook:'The traveler separates a stolen ledger from cargo that was never taken.', startTitle:'An Empty Hook', start:'At the freight yard, clerk Amos Bell finds a cut strap and an empty hook where the waybill ledger hung. The wagon is still sealed and every crate is accounted for. A boot track crosses the yard toward the canal, but the clerk has not yet checked the night book.', approaches:[{id:'checkSeal',label:'Check the wagon seals before following tracks',result:'Every cargo seal is intact; the missing ledger could describe loads but does not prove one was stolen.'},{id:'questionNightman',label:'Ask the night watch what he heard',result:'He heard one cart leave toward the canal but did not see who drove it.'},{id:'followTrack',label:'Follow the boot track only as far as the public lane',result:'The track reaches the lane and disappears among ordinary cart marks.'}], threatTitle:'The Clerk Returns', threat:'Bell reappears from the siding office with the ledger wrapped under his coat. He says a stranger took it briefly to copy one freight number; the stranger is now waiting beyond the yard gate.', responses:[{id:'askNumber',label:'Ask which freight number was copied',result:'The number belongs to a county tool shipment that was misrouted last week.'},{id:'secureBook',label:'Keep the ledger in the locked office until the owner arrives',result:'The book is secured without accusing the night watch or opening the sealed cargo.'},{id:'callWitness',label:'Ask the yard foreman to witness the return',result:'The foreman signs that the ledger is back and the freight seals remain whole.'}], aftermathTitle:'A Number, Not a Missing Load', aftermath:'The copied number points to a misplaced public-works crate, not a successful cargo theft. The railway will trace it by the signed waybill.', endings:[{id:'traceCrate',label:'Help the clerk send the corrected waybill',result:'The crate can be redirected without opening the other freight.'},{id:'leaveLedger',label:'Leave the ledger under the foreman’s custody',result:'The yard keeps the book locked until the county clerk confirms the shipment.'}], rewardText:'The foreman offers a duplicate Lockable Map Case for carrying the signed waybill to the county office.', gear:'lockableMapCase',gearName:'Lockable Map Case',provenance:'The foreman transfers a surplus case issued to the yard; the official ledger stays locked at work.', coins:2, lesson:'A missing record and missing cargo are different claims; check seals before assuming a load was stolen.', lore:'The canal siding once carried county survey tools before the rail extension.' },
  { id:'the-horse-with-the-blue-rope', title:'The Horse with the Blue Rope', subtitle:'A horse is led away from a waystation, but the person holding the rope may have permission.', risk:'MODERATE', setting:'farm lane and waystation', activity:'animals', hook:'The Traveler must verify ownership before treating a horse’s movement as theft.', startTitle:'A Horse Led at Dawn', start:'At dawn a blue rope leads a bay horse away from the waystation. The stablehand says the owner left before sunrise but cannot remember whether the horse was paid out. A folded note is pinned beneath the stable ledger.', approaches:[{id:'readNote',label:'Read the pinned note with the stablehand present',result:'The note asks the stablehand to release the bay after a final payment, but the amount is blank.'},{id:'followAtDistance',label:'Follow the pair along the open lane',result:'The rider leads the horse at a walk and does not look back toward the stable.'},{id:'checkBook',label:'Check the stable book for a signed release',result:'A payment mark is present but the owner’s signature is smudged by rain.'}], threatTitle:'Two People Claim One Horse', threat:'At the lane gate, the rider says the horse was promised as payment. The stablehand catches up and says the final fee was never settled. The horse is calm; a farm owner nearby recognizes the tack, not the rider.', responses:[{id:'askFarmOwner',label:'Ask the farm owner to identify the tack',result:'The farm owner confirms the saddle belongs to the stable, but cannot say who owns the horse.'},{id:'offerLedger',label:'Return to the ledger and settle the payment record',result:'The book shows an unpaid balance; the rider agrees to leave the horse until the owner is reached.'},{id:'separateClaims',label:'Keep the horse at the gate while both accounts are written down',result:'The stablehand takes the lead and the rider leaves without the animal.'}], aftermathTitle:'A Horse Kept from a Guess', aftermath:'A telegraph reply confirms the owner authorized release only after the final fee. The rider had not paid it. The stable retains the horse and tack until the owner arrives.', endings:[{id:'stayForOwner',label:'Wait with the stablehand for the owner',result:'The horse stays in its familiar stall and the rider’s account is recorded.'},{id:'leaveRecord',label:'Leave the written accounts for the owner',result:'The stable has both statements and will not release the horse on an unsigned note.'}], rewardText:'The stablehand pays the agreed two-coin fee for helping preserve the horse and its records.', gear:'heavyLeatherGloves',gearName:'Heavy Leather Gloves',provenance:'No horse or disputed tack changes hands; the gloves are the stable owner’s separate, paid work gloves released as compensation.', coins:2, lesson:'A familiar bridle or saddle can identify equipment without proving who owns the animal wearing it.' },
  { id:'the-lantern-in-the-hedge', title:'The Lantern in the Hedge', subtitle:'A night traveler’s lamp goes dark before a voice asks for the purse.', risk:'HIGH', setting:'hedgerow road', activity:'survival', hook:'A staged light failure forces the traveler to choose whether to reveal their position.', startTitle:'A Flame Goes Out', start:'Your lantern gutters beside a high hedge. A voice from the far side asks you to set your purse on the ground. You can see no face, and the road behind remains open. A second, weaker light moves farther down the hedge.', approaches:[{id:'shieldFlame',label:'Lower the lantern behind your coat and preserve darkness',result:'Your outline disappears while the distant light continues toward the road bend.'},{id:'raiseLamp',label:'Raise the lantern to show empty hands',result:'The light reveals a narrow gap in the hedge, but not the speaker.'},{id:'backToGate',label:'Move toward the farm gate without answering',result:'The gate is within a few steps; the unseen person moves parallel to you.'}], threatTitle:'A Second Voice', threat:'Two people step onto the road several paces apart. One holds a lantern with a dented wire guard and the other watches the farm gate. They ask again for your purse; neither has closed the route behind you.', responses:[{id:'callHouse',label:'Call to the farmhouse beyond the gate',result:'A house light comes on and both figures retreat toward the far hedge.'},{id:'leavePurse',label:'Set down a small coin purse and step back',result:'The nearer figure takes the purse while you reach the gate; no one follows.'},{id:'holdGate',label:'Keep the gate between you and the nearer figure',result:'The gate blocks the approach long enough for the farmhouse to answer.'}], aftermathTitle:'A Guard Left Behind', aftermath:'At daylight the farmer finds the robbers’ lantern guard beside the hedge. Its glass is broken; the guard is still serviceable, but the lamp itself belongs to the farmer and is returned.', endings:[{id:'reportNight',label:'Give the farmer and constable your account',result:'They record the demand and the purse you surrendered, without claiming the robbers were identified.'},{id:'leaveHedge',label:'Leave before the road grows busy',result:'You reach the next village by daylight, poorer by the coins surrendered but otherwise safe.'}], rewardText:'The farmer lets you keep the recovered guard after the constable confirms it was abandoned; the damaged lantern is not taken.', gear:'lanternGuard',gearName:'Lantern Guard',provenance:'The farmer and constable identify the cage as abandoned criminal equipment and release it; the owner’s lantern is returned.', coins:1, lesson:'A guard protects lantern glass from knocks, not from a deliberate theft or a failing flame.', combat:{enemy:'hedge-road thieves',winChance:.48,damage:5,win:'The thieves withdraw when the farmhouse answers; the lamp and purse remain with their rightful owners.',loss:'You are struck while reaching the gate, but the farmer opens it and the thieves flee.'} },
  { id:'the-bridge-keeper-isnt-home', title:'The Bridge Keeper Isn’t Home', subtitle:'A rope blocks the bridge, and the posted fee does not match the county notice.', risk:'MODERATE', setting:'covered bridge', activity:'negotiation/trade', hook:'A traveler verifies a disputed crossing fee without assuming that every keeper is a robber.', startTitle:'A Fee in Chalk', start:'A rope bars the covered bridge. A hand-painted board asks for two coins, while the county notice beside it lists one. The bridge keeper’s cottage is shuttered; a wagon waits behind you and the far bank is visible.', approaches:[{id:'compareNotice',label:'Read the county notice and note its date',result:'The notice is current and bears a county seal; the chalk board has no signature.'},{id:'askWagoner',label:'Ask the waiting wagoner what they paid yesterday',result:'The wagoner says the fee was one coin, paid to the keeper’s daughter.'},{id:'waitKeeper',label:'Wait for the keeper before touching the rope',result:'A child arrives from the cottage and says the keeper is at the mill.'}], threatTitle:'A Man Claims the Fee', threat:'A stranger steps from beneath the bridge and calls himself the keeper’s collector. He wants the full two coins and points to a knife on his belt. The wagon can still turn back on the broad bank.', responses:[{id:'offerOne',label:'Offer the posted one coin and ask for a receipt',result:'The stranger refuses the receipt; the wagoner hears him and starts calling for the mill.'},{id:'turnBack',label:'Turn the wagon around and report the false fee',result:'The wagon backs to the farm road while the stranger leaves the bridge.'},{id:'askKeeperProof',label:'Ask him to name the county notice date',result:'He gives the wrong year and retreats when the wagoner repeats the correct date.'}], aftermathTitle:'A Crossing with a Record', aftermath:'The keeper returns from the mill and confirms the stranger had no authority to collect fees. The bridge remains closed until the rope is removed and the county notice is copied.', endings:[{id:'copyNotice',label:'Help copy the current fee notice',result:'Travelers can compare the fee before crossing; no one pays the false collector.'},{id:'escortWagon',label:'Wait until the keeper reopens the bridge',result:'The wagon crosses after the keeper records the false toll attempt.'}], rewardText:'The keeper releases a spare Freightman’s Strap as thanks for helping protect the wagon queue.', gear:'freightmansStrap',gearName:'Freightman’s Strap',provenance:'The bridge keeper transfers a privately owned spare strap after reopening the bridge; the county’s barrier rope stays in place.', coins:2, lesson:'A posted fee and a receipt matter more than a stranger’s claim to collect for the county.', combat:{enemy:'false toll collector',winChance:.46,damage:5,win:'The collector retreats when the wagoner and keeper arrive together.',loss:'You are bruised in the struggle; the wagoner turns back while the keeper fetches help.'} },
  { id:'the-punctured-tireless-wheel', title:'The Wheel with the Clean Cut', subtitle:'A stopped wagon has a neat cut in its trace and a missing tool roll.', risk:'HIGH', setting:'muddy farm road', activity:'labor/repair', hook:'A repair problem becomes evidence of theft, but the Traveler must still get the wagon out safely.', startTitle:'A Team Held at the Roadside', start:'A wagon is stopped in thick mud. Its trace has a clean cut, the rear wheel is sound, and the driver’s tool roll is gone. Fresh hoofprints lead toward a tree line; the team is restless but uninjured.', approaches:[{id:'calmTeam',label:'Calm the team before inspecting the cut',result:'The horses settle and the cut appears to have been made with a sharp edge, not torn under strain.'},{id:'coverWagon',label:'Move the wagon under the roadside shelter',result:'The driver reaches firm ground, though the missing tool roll remains unaccounted for.'},{id:'followPrints',label:'Follow the hoofprints only to the field fence',result:'The prints turn north at the fence and a second set comes back toward the road.'}], threatTitle:'The Tool Roll Returns', threat:'A young rider appears with the tool roll and says an older partner ordered them to take it as payment. The partner waits near the creek, where the road narrows and the team cannot turn easily.', responses:[{id:'askYoungRider',label:'Ask the rider to return the roll and leave',result:'The rider sets it beside the wagon and rides north alone.'},{id:'freeTeam',label:'Move the team to firm ground before confronting anyone',result:'The driver leads the horses out of the mud while the rider leaves the roll behind.'},{id:'callFenceFarmer',label:'Call the fence farmer to witness the return',result:'The farmer answers; the rider abandons the tool roll and flees.'}], aftermathTitle:'A Repair Before Pursuit', aftermath:'The driver confirms the tool roll belongs to the wagon. The trace can be spliced with the Freightman’s Strap, but the older partner is gone into the creek brush.', endings:[{id:'spliceTrace',label:'Help splice the trace and return the tools',result:'The wagon reaches the farm without pursuing anyone into the narrow creek.'},{id:'reportTrace',label:'Leave the trace for the smith and report the rider',result:'The horses are walked to the farm; the tool roll is returned intact.'}], rewardText:'The driver pays you the agreed repair fee; no stolen item is kept as a reward.', gear:'pocketToolkit',gearName:'Pocket Toolkit',provenance:'The driver gives a separate, used toolkit from the wagon’s duplicate stock after the owner confirms the recovered roll is complete.', coins:3, lesson:'A clean cut can be evidence of deliberate interference, but the trace still needs a safe repair before travel.' },
  { id:'the-inn-yard-watch', title:'The Inn-Yard Watch', subtitle:'Someone has been taking bridles from the stable while guests sleep.', risk:'LOW', setting:'inn stable yard', activity:'investigation/mystery', hook:'A stable theft is solved through observation rather than a roadside fight.', startTitle:'An Empty Peg', start:'The inn host shows you three empty bridle pegs. The guests are still asleep, the stable door has no broken latch, and hoofprints lead to the yard gate. A stable boy insists no horse left overnight.', approaches:[{id:'checkHorses',label:'Count the horses before questioning the boy',result:'All horses are present; only spare bridles are missing.'},{id:'inspectLatch',label:'Inspect the latch without disturbing it',result:'The latch was opened with its own key, not forced.'},{id:'watchGate',label:'Watch the gate from the hayloft',result:'A kitchen hand approaches with one bridle and stops when they see you.'}], threatTitle:'A Familiar Key', threat:'The kitchen hand says a cousin borrowed the bridles for a night ride and planned to return them before dawn. One bridle has a cracked cheek strap; the host says the stable’s property must be accounted for.', responses:[{id:'askCousin',label:'Ask the hand to bring the cousin back with the bridles',result:'The cousin arrives and returns the bridles, admitting the ride was not authorized.'},{id:'checkCrack',label:'Show the host the cracked strap before accepting the return',result:'The host documents the damaged strap and separates it from the sound tack.'},{id:'wakeGuests',label:'Wake the horse owners and let them witness the return',result:'The guests identify their own tack and agree to leave the matter with the host.'}], aftermathTitle:'The Stable Is Accounted For', aftermath:'Every bridle is back with its owner. The cracked strap belongs to the inn and will be repaired; no guest’s horse was taken.', endings:[{id:'helpRepair',label:'Help the host sort the sound tack from the damaged piece',result:'The host locks the spare key away and sends the damaged bridle to the saddler.'},{id:'leaveStable',label:'Leave after the owners identify their gear',result:'The inn records the return and the stable boy is not blamed for a key he did not use.'}], rewardText:'The host pays you one coin for the night watch and lets you keep the spare lockable case used to store the stable’s duplicate keys.', gear:'lockableMapCase',gearName:'Lockable Map Case',provenance:'The host transfers a separate, privately owned case after removing the inn’s key ledger; no owner’s document leaves the stable.', coins:1, lesson:'An intact lock and missing property may point to a copied or borrowed key rather than a forced entry.' },
  { id:'the-mill-road-pursuit', title:'The Mill-Road Pursuit', subtitle:'A wagoner recognizes the stolen axle pin by its hand-cut notch.', risk:'HIGH', setting:'mill road and wooded lane', activity:'travel/exploration', hook:'A chase is a choice with costs, not an automatic obligation to catch a thief.', startTitle:'A Cart Going Too Fast', start:'A miller calls from the road: a handcart has taken a boxed axle pin from his yard and is moving downhill. The cart is light, the driver is young, and a second person walks behind it watching the road.', approaches:[{id:'warnMiller',label:'Ask the miller what was taken and who owns it',result:'The pin is the mill’s spare, marked with a hand-cut notch.'},{id:'warnRoad',label:'Warn the next wagon before following',result:'A wagon stops at the fork, leaving the cart without a clear path through traffic.'},{id:'followCart',label:'Follow at a distance along the mill road',result:'The walker looks back twice but does not yet run.'}], threatTitle:'The Cart Tips', threat:'The cart hits a rut and tips. The pin rolls toward the ditch; the young driver tries to lift the cart alone while the second person reaches for the pin.', responses:[{id:'securePin',label:'Recover the marked pin while the driver steadies the cart',result:'You return the mill’s pin before the pair can leave the road.'},{id:'helpDriver',label:'Help lift the cart before anyone reaches for the pin',result:'The driver admits the older companion promised payment for a pin they did not own.'},{id:'callMiller',label:'Call the miller down the road',result:'The miller arrives and identifies the pin; the pair set it down and walk away.'}], aftermathTitle:'The Mill’s Mark', aftermath:'The pin is returned to the miller. The driver says the theft was arranged by an older partner, but does not know their name or destination.', endings:[{id:'walkBack',label:'Walk the pin back to the mill',result:'The miller checks the notch and secures the pin with the other spare fittings.'},{id:'escortDriver',label:'Walk the young driver to the village office',result:'The miller keeps the pin and the driver gives an account without being chased into the trees.'}], rewardText:'The miller gives you his duplicate Carriage Jack after the road is clear and the pin is returned.', gear:'foldingCarriageJack',gearName:'Folding Carriage Jack',provenance:'The miller transfers a personal spare, not the recovered pin or any property taken from the young driver.', coins:2, lesson:'A hand-cut mark can identify a particular part; the cart’s direction alone cannot identify its owner.', combat:{enemy:'axle-pin thieves',winChance:.48,damage:4,win:'The older companion leaves the pin and retreats when the miller arrives.',loss:'You are bruised as the pair flee; the pin rolls into the grass but the miller recovers it.'} },
  { id:'the-letter-under-the-seat', title:'The Letter Under the Seat', subtitle:'A coach passenger says a robber searched the wrong bag for a letter.', risk:'MODERATE', setting:'stagecoach stop', activity:'communication/witness', hook:'The traveler must protect a private letter while helping identify a false claim about stolen papers.', startTitle:'A Passenger Waits Behind', start:'At a coach stop, passenger Hester Quill refuses to board until a letter is found. A man searched her bag at the last halt and rode away with an empty envelope. The coach leaves in ten minutes; the station clerk can hold it if asked.', approaches:[{id:'askEnvelope',label:'Ask Quill what was written on the envelope',result:'She says it carried no address and contained no letter when the man took it.'},{id:'checkSeat',label:'Check beneath the coach seat without opening luggage',result:'A folded note is caught in the seat rail; its seal is intact.'},{id:'askClerk',label:'Ask the station clerk to hold the coach',result:'The clerk agrees to delay departure briefly while Quill checks her own things.'}], threatTitle:'The Rider Returns', threat:'The man returns and says the letter is his. He has a railway receipt with a torn corner; Quill has the matching half but says the note is addressed to someone else.', responses:[{id:'matchReceipt',label:'Compare the torn receipt halves in front of the clerk',result:'The halves match and show the man paid to carry an empty envelope, not Quill’s sealed note.'},{id:'letQuillDecide',label:'Let Quill decide whether to speak to him',result:'Quill refuses the claim and asks the clerk to record the man’s name.'},{id:'holdCoach',label:'Ask the clerk to hold the coach until the constable arrives',result:'The man leaves when the clerk rings the station bell.'}], aftermathTitle:'A Letter Still Sealed', aftermath:'Quill keeps her private note. The man’s receipt confirms a paid delivery but not ownership of the letter; the clerk logs the interruption.', endings:[{id:'boardTogether',label:'Board with Quill after the clerk records the account',result:'The coach leaves with the note still sealed and its intended reader unknown to everyone else.'},{id:'stayClerk',label:'Stay until the constable hears both accounts',result:'Quill waits with the clerk rather than hand a private letter to a stranger.'}], rewardText:'Quill gives you a duplicate Lockable Map Case, purchased for the journey and no longer needed now that the letter is safe.', gear:'lockableMapCase',gearName:'Lockable Map Case',provenance:'Quill explicitly gifts her separately purchased spare case after retaining her own letter and papers.', coins:2, lesson:'A matching receipt can establish a delivery arrangement without proving the delivered object belongs to the messenger.' },
  { id:'the-second-rope', title:'The Second Rope', subtitle:'A traveler finds a wagon team tied to a tree while the owner is held at a distance.', risk:'HIGH', setting:'mountain pass road', activity:'rescue/care', hook:'A restrained team and a visible retreat route turn an attempted robbery into a rescue and property decision.', startTitle:'A Team Without a Driver', start:'Two draft horses stand tied on a narrow pass. Their wagon is empty and its brake is set. From the uphill side you hear a person call for help; the downhill track remains open but steep.', approaches:[{id:'steadyHorses',label:'Approach the horses from the open downhill side',result:'The horses stay calm; a lead rope has been cut and retied around the tree.'},{id:'callOwner',label:'Call out before moving toward the voice',result:'A driver answers from behind a rock shelf and says two people took the cargo.'},{id:'markRetreat',label:'Mark the downhill retreat before investigating',result:'You mark a safe turn-around point where a wagon could pass without meeting the attackers.'}], threatTitle:'The Cargo Is Still Near', threat:'One robber stands above the wagon with a short rope; another is out of sight. The driver is unhurt but cannot reach the team. The robber says the cargo is payment for passage.', responses:[{id:'freeTeam',label:'Use your Travel Rope to make a second lead',result:'The team can be walked downhill without approaching the robber.',requiresItem:'travelRope'},{id:'callDriver',label:'Keep the driver behind the rock and ask for the cargo owner',result:'The robber cannot name the owner and backs away from the wagon.'},{id:'offerRetreat',label:'Offer a clear route off the pass if the cargo stays',result:'The robber leaves the cargo and takes the uphill trail.'}], aftermathTitle:'A Team Walked Downhill', aftermath:'The driver confirms the cargo belongs to a nearby sawmill and remains sealed. The two robbers have left the pass; no one follows them into the steep brush.', endings:[{id:'deliverCargo',label:'Walk the team and cargo to the sawmill',result:'The owner checks each seal before accepting the load.'},{id:'stayWithDriver',label:'Stay with the driver until another team arrives',result:'The horses remain at the safe turn-around while the driver waits for help.'}], rewardText:'The sawmill owner pays the contracted recovery fee after the cargo seals are counted.', gear:'ironRopeClamp',gearName:'Iron Rope Clamp',provenance:'The owner gives a spare clamp from the sawmill’s duplicate line kit as a documented recovery fee.', coins:3, lesson:'A second line can control a team’s movement without forcing a confrontation on narrow ground.', combat:{enemy:'passage robber',winChance:.5,damage:5,win:'The robber abandons the cargo and retreats uphill; the driver and team remain together.',loss:'You are hurt near the rock shelf, but the driver reaches the team and leads it down the marked route.'} },
  { id:'the-brass-notch', title:'The Brass Notch', subtitle:'A supposed railway inspector cannot explain the tool marks on a siding lock.', risk:'MODERATE', setting:'rail siding', activity:'investigation/mystery', hook:'A disguised freight thief is exposed through equipment evidence, not a badge or stereotype.', startTitle:'An Inspection After Hours', start:'A man in a railway coat asks you to help open a siding cabinet after dark. His badge is the correct shape but has no number. The night clerk is inside the lamp room, and the cabinet lock shows fresh brass filings.', approaches:[{id:'askClerk',label:'Ask the night clerk to verify the order',result:'The clerk says no inspection was scheduled and the foreman has the only key.'},{id:'studyLock',label:'Inspect the filings without touching the lock',result:'The cut is from a narrow file, not the railway key.'},{id:'askBadge',label:'Ask the man which yard issued his badge',result:'He names the neighboring division but gives the wrong supervisor.'}], threatTitle:'The Cabinet Opens', threat:'The man produces a small pry tool and says the cabinet holds a payroll receipt he is owed. The clerk has stepped into the lit doorway; the siding gate is open toward town.', responses:[{id:'keepDoor',label:'Stand in the doorway and ask the clerk to call the foreman',result:'The man sets down the pry tool and leaves before the foreman arrives.'},{id:'offerWitness',label:'Ask the clerk to record the badge and tool marks',result:'The man backs away from the cabinet when his actions are written down.'},{id:'followAtDistance',label:'Let him leave and note which road he takes',result:'He walks toward town without the cabinet contents; the clerk retains the evidence.'}], aftermathTitle:'The Cabinet Stays Shut', aftermath:'The foreman confirms the man was not assigned to the siding. The payroll receipt remains in the locked cabinet until the clerk can reconcile its records.', endings:[{id:'repairLock',label:'Help the foreman replace the damaged lock',result:'The lock is replaced and the filings are kept with the incident report.'},{id:'leaveYard',label:'Leave after the clerk has a witness',result:'The clerk closes the yard gate and the foreman will file the badge description.'}], rewardText:'The foreman transfers a spare Pocket Toolkit from the siding’s retired tool board as thanks for protecting the cabinet.', gear:'pocketToolkit',gearName:'Pocket Toolkit',provenance:'The railway foreman signs out a duplicate tool retired from service; the cabinet property stays secured.', coins:2, lesson:'A badge can be copied; tool marks and a verifiable work order are stronger evidence.', combat:{enemy:'siding thief',winChance:.45,damage:5,win:'The thief drops the pry tool and runs through the open gate when the foreman arrives.',loss:'You are struck near the door, but the clerk shuts the cabinet and calls the night watch.'} },
  { id:'the-ferry-chain', title:'The Ferry Chain', subtitle:'A ferry is held at the bank by a cut chain, and a stranger offers to sell passage.', risk:'HIGH', setting:'river ferry landing', activity:'travel/exploration', hook:'An attempted ferry extortion can be answered by restoring the crossing, waiting, or exposing the false operator.', startTitle:'A Ferry That Will Not Pull', start:'The ferry rests at the far bank. Its chain is cut at the near post, and a stranger offers to row passengers across for a fee. The ferryman is nowhere in sight; a small skiff is tied upstream to a willow.', approaches:[{id:'inspectPost',label:'Inspect the cut chain from the bank',result:'The chain was cut cleanly with a saw; the post itself is sound.'},{id:'findFerryman',label:'Call for the ferryman before paying anyone',result:'A voice answers from the ferry shed; the ferryman is inside and unhurt.'},{id:'watchSkiff',label:'Watch the upstream skiff without approaching it',result:'Someone moves beneath the willow and then leaves the skiff behind.'}], threatTitle:'The Ferry Fee', threat:'The stranger says the ferryman owes him money and blocks the landing with an oar. The river is too fast for a swim; the ferry remains tied across the channel, and the shed door opens onto the road.', responses:[{id:'callFerryman',label:'Call the ferryman into view',result:'The ferryman appears with a neighbor; the stranger drops the oar and leaves.'},{id:'waitBank',label:'Keep everyone on firm ground and wait for help',result:'A second boat arrives from downstream and the stranger walks away.'},{id:'showCut',label:'Point out the clean chain cut and ask for a receipt',result:'The stranger cannot explain the cut or produce a receipt, then leaves the landing.'}], aftermathTitle:'A Crossing Delayed', aftermath:'The ferryman confirms the stranger had no claim to the landing. The chain will need a smith’s link; the ferry stays at the far bank until it is repaired.', endings:[{id:'sendForSmith',label:'Walk to the smith for a chain link',result:'The ferryman keeps the landing closed until the repair is witnessed.'},{id:'waitForOtherBoat',label:'Wait for the downstream boat',result:'Passengers cross safely by the other landing, though the ferry service is delayed.'}], rewardText:'The ferryman gives you a privately owned Weatherproof Cloak from his spare locker for keeping passengers from attempting the dangerous water.', gear:'weatherproofCloak',gearName:'Weatherproof Cloak',provenance:'The ferryman explicitly gifts his own spare cloak; no ferry equipment or passenger property is taken.', coins:2, lesson:'A cut ferry chain can disable a crossing without making the river itself passable.', combat:{enemy:'ferry extortionist',winChance:.47,damage:5,win:'The stranger leaves the landing when the ferryman and neighbor appear together.',loss:'You are knocked down on the bank, but the ferryman gets passengers inside the shed and calls for help.'} },
  { id:'the-courier-who-came-back', title:'The Courier Who Came Back', subtitle:'A courier returns with an empty satchel and a story that does not match the road dust.', risk:'LOW', setting:'inn yard and county road', activity:'investigation/mystery', hook:'The traveler helps a courier separate a robbery claim from an ordinary lost delivery.', startTitle:'An Empty Satchel', start:'Courier Silas Penn reaches the inn with an empty satchel and says he was robbed. His coat is dusty on the front but clean across the back; he says he fell in the road. The innkeeper knows the delivery was addressed to the county clerk.', approaches:[{id:'askRoute',label:'Ask which road he took and where he fell',result:'Penn names the north road, though the mud on his boots is from the south lane.'},{id:'checkReceipt',label:'Check the delivery receipt before questioning further',result:'The receipt is signed at the inn, not at the county office.'},{id:'letRest',label:'Offer water and let him rest before continuing',result:'Penn’s account becomes clearer after he sits; he says the satchel was left at a milepost.'}], threatTitle:'The Satchel Is Found', threat:'A stablehand brings the satchel from the south lane. It is empty except for a torn wrapper and no broken lock. Penn says the wrapper held the county papers; the innkeeper has not seen them.', responses:[{id:'searchWrapper',label:'Examine the wrapper for its office mark',result:'The wrapper bears the county clerk’s stamp and a delivery number.'},{id:'askStablehand',label:'Ask who carried the satchel from the lane',result:'The stablehand found it beside the road and did not open it.'},{id:'compareReceipt',label:'Compare the number with the inn register',result:'The register shows no sealed papers were handed to Penn here.'}], aftermathTitle:'No Papers in the Satchel', aftermath:'The county clerk confirms the papers were never placed in the satchel. Penn was meant to carry a receipt, not the documents; the robbery claim has no stolen property behind it.', endings:[{id:'correctAccount',label:'Help Penn correct the account with the clerk',result:'The clerk records a lost satchel but no missing public document.'},{id:'leaveMatter',label:'Leave the innkeeper to settle the delivery fee',result:'Penn returns the empty satchel and the clerk resolves the charge privately.'}], rewardText:'The innkeeper pays one coin for the careful account and gives no further reward.', gear:'conductorWhistle',gearName:'Conductor’s Whistle',provenance:'The innkeeper has no whistle to transfer; this route is coin-only, so no Gear is awarded.', coins:1, lesson:'An empty container is not proof that its stated contents were carried or stolen.' },
  { id:'the-closed-gate', title:'The Closed Gate', subtitle:'A ranch gate is chained from the far side while a family wagon waits on the road.', risk:'MODERATE', setting:'farm lane and pasture gate', activity:'negotiation/trade', hook:'A road obstruction is a property dispute first; force is neither the only nor default answer.', startTitle:'A Chain Across the Lane', start:'A wagon family cannot reach the county road because the gate is chained from the pasture side. The rancher says the chain is new; the family says the lane has always been public. A sign marks the surveyed boundary beyond the gate.', approaches:[{id:'readSign',label:'Read the boundary sign before touching the chain',result:'The sign identifies the lane as a recorded right-of-way, subject to a seasonal livestock closure.'},{id:'askFamily',label:'Ask the family whether they know the seasonal closure',result:'They have a dated permit but do not know whether the date begins today.'},{id:'findRancher',label:'Walk the fence to find the rancher',result:'You find the rancher repairing a post and hear that two strangers cut the chain last night.'}], threatTitle:'Two Riders at the Fence', threat:'Two riders arrive and claim the gate fee is theirs to collect. The rancher says he did not hire them. They have a coil of chain and stand between the wagon and the open lane.', responses:[{id:'showPermit',label:'Show the dated permit and ask for the rancher’s witness',result:'The riders leave when the rancher confirms the closure had not begun.'},{id:'openBackLane',label:'Lead the family to the marked back lane',result:'The wagon takes the longer public route without crossing the gate.'},{id:'callNeighbor',label:'Call the neighboring farm to witness the claim',result:'A neighbor arrives and the riders abandon the chain.'}], aftermathTitle:'The Right-of-Way Remains', aftermath:'The chain belongs to the strangers, not the rancher. The family reaches the road by the back lane while the county clerk is asked to confirm the permit date.', endings:[{id:'leaveChain',label:'Leave the cut chain for the county clerk',result:'The chain is tagged as evidence and the gate remains open to permitted traffic.'},{id:'helpFamily',label:'Walk with the family to the county road',result:'The family reaches the road without paying an unauthorized toll.'}], rewardText:'The rancher transfers a spare Freightman’s Strap from his own wagon kit for helping protect the right-of-way.', gear:'freightmansStrap',gearName:'Freightman’s Strap',provenance:'The rancher owns and explicitly gifts the spare strap; the cut chain remains evidence.', coins:2, lesson:'A public right-of-way may still have seasonal rules; verify the date before removing a barrier.', combat:{enemy:'gate-fee extortionists',winChance:.48,damage:5,win:'The riders abandon the chain and leave when the neighbor arrives.',loss:'You are hurt at the fence, but the family uses the open back lane while the rancher summons help.'} },
  { id:'the-camp-with-two-fires', title:'The Camp with Two Fires', subtitle:'A second fire appears beyond a caravan camp after the night watch hears a horse move.', risk:'HIGH', setting:'prairie caravan camp', activity:'survival', hook:'An attempted camp raid is discovered early; the player chooses protection and evidence over automatic pursuit.', startTitle:'A Fire Beyond the Wagons', start:'The camp cook sees a second fire beyond the wagon ring. A horse’s lead is slack, but the animal remains inside the line. The watchman heard a buckle click and found no one at the gate.', approaches:[{id:'secureHorse',label:'Secure the horse before checking the second fire',result:'The lead is tied twice and the horse settles beside the cook wagon.'},{id:'countLoads',label:'Count the loads under canvas from inside the ring',result:'The tool chest is still present, but one strap has been unfastened.'},{id:'wakeCamp',label:'Wake the camp quietly and keep everyone inside the ring',result:'The second fire dims when voices rise, but its maker remains unseen.'}], threatTitle:'A Hand at the Tool Chest', threat:'A person crawls between two wagons toward the unlocked tool chest. The camp ring is lit by a lantern, and the open prairie behind the intruder offers no cover.', responses:[{id:'callWatch',label:'Call the watchman and keep clear of the wagons',result:'The watchman blocks the exit; the intruder drops a pry tool and surrenders.'},{id:'closeGap',label:'Close the wagon gap without cornering the person',result:'The intruder turns toward the open gate and leaves without the chest.'},{id:'wakeCook',label:'Ask the cook to sound the camp whistle',result:'The camp wakes together; the intruder flees, leaving the tool chest untouched.'}], aftermathTitle:'A Chest Still Owned', aftermath:'The chest belongs to the caravan and remains closed. The watchman recognizes the intruder as a former hand who left over unpaid wages; the owner will settle that dispute in town.', endings:[{id:'returnTool',label:'Return the dropped pry tool to its owner',result:'The owner identifies the tool as caravan property and logs it back into the chest.'},{id:'escortFormerHand',label:'Walk the former hand to the town office',result:'The camp keeps its property and the wage claim can be heard without a night pursuit.'}], rewardText:'The caravan owner releases a separate Folding Pry Tool from the duplicate repair kit as compensation for the watch.', gear:'foldingPryTool',gearName:'Folding Pry Tool',provenance:'The owner signs out a duplicate tool from the caravan’s private repair kit; the dropped tool is returned to the chest.', coins:2, lesson:'A lit camp ring and a clear exit can prevent a theft from becoming a fight.', lore:'The two-fire signal was once used by teamsters to distinguish a camp from a false roadside light.', combat:{enemy:'former caravan hand',winChance:.53,damage:4,win:'The former hand surrenders when the watchman closes the gate; the chest stays untouched.',loss:'You are struck in the narrow wagon gap, but the watchman secures the chest and the intruder flees.'} },
  { id:'the-blue-thread', title:'The Blue Thread', subtitle:'A traveler’s coat is caught on a thorn beside a road where a purse was taken.', risk:'LOW', setting:'woodland road', activity:'investigation/mystery', hook:'A small trace helps locate a surrendered purse without turning suspicion into a conviction.', startTitle:'A Thread on the Thorn', start:'A woman named Ruth Vale asks whether you saw a blue thread on the road. Her purse is missing, but she says she may have dropped it while helping a child cross a ditch. A thorn holds blue wool at waist height.', approaches:[{id:'checkDitch',label:'Check the ditch where the child crossed',result:'The child’s bootprints reach the far bank; no purse lies in the mud.'},{id:'askWitness',label:'Ask the nearby woodcutter what passed',result:'The woodcutter saw a person carrying a blue scarf, not necessarily Vale’s purse.'},{id:'followThread',label:'Follow the loose blue fibers along the hedge',result:'The fibers lead toward a resting place beside the road, then stop.'}], threatTitle:'The Purse Is on the Bench', threat:'A tired traveler sits at the resting bench with Vale’s purse beside them. They say they found it and waited, but the clasp is open and a few coins are missing. Vale recognizes the stitching, not the finder.', responses:[{id:'countCoins',label:'Ask Vale to identify the contents without opening the purse',result:'Vale names the number of coins and a folded laundry ticket.'},{id:'askFinder',label:'Ask the traveler to describe where they found it',result:'The traveler points to the ditch and admits they took two coins for food.'},{id:'callWoodcutter',label:'Ask the woodcutter to witness the return',result:'The woodcutter confirms the purse was on the bench before either traveler arrived.'}], aftermathTitle:'A Purse Returned', aftermath:'Vale identifies her laundry ticket and takes back the purse. The finder returns the remaining coins and admits taking two; Vale decides whether to report the loss.', endings:[{id:'leaveReport',label:'Let Vale decide whether to report the missing coins',result:'The purse is returned; no one else decides whether a small loss merits a charge.'},{id:'walkToInn',label:'Walk with both travelers to the innkeeper',result:'The innkeeper records the returned purse and the finder’s account.'}], rewardText:'Vale thanks you with one coin and keeps the purse and its contents.', gear:'fieldBandageRoll',gearName:'Field Bandage Roll',provenance:'No property changes hands as a reward; Vale pays a small tip. The listed Gear is not awarded on this coin-only route.', coins:1, lesson:'A found object’s location and its finder’s account matter; neither alone proves theft.' },
  { id:'the-axle-without-a-mark', title:'The Axle without a Mark', subtitle:'A cart axle has been taken from a public road crew, leaving a loaded wagon stranded.', risk:'MODERATE', setting:'county road works', activity:'labor/repair', hook:'A stolen repair part must be returned before the traveler accepts any compensation.', startTitle:'A Wagon on Three Wheels', start:'A road crew’s handcart has lost its spare axle. A loaded wagon is stranded nearby with one wheel tilted. The foreman says the missing axle was marked with a blue paint stripe; a blacksmith’s yard lies down the lane.', approaches:[{id:'stabilizeWagon',label:'Help unload the wagon before moving its wheel',result:'The load is moved to firm ground, taking pressure off the damaged axle.'},{id:'checkCrewBook',label:'Check the crew inventory before accusing anyone',result:'The axle was signed out for a repair demonstration yesterday.'},{id:'askSmith',label:'Ask the smith whether an axle was brought in',result:'The smith confirms no road-crew axle has arrived today.'}], threatTitle:'A Mark in the Blacksmith Yard', threat:'A stranger offers to sell a blue-striped axle from a handcart. The foreman recognizes the stripe; the stranger says it was abandoned in a ditch. The cart’s serial stamp is still visible beneath the mud.', responses:[{id:'checkStamp',label:'Clean the stamp and compare it with the crew book',result:'The stamp matches the road crew inventory; the axle was stolen, not abandoned.'},{id:'callForeman',label:'Ask the foreman to claim the axle in writing',result:'The foreman signs the claim and the smith keeps the axle inside.'},{id:'refusePurchase',label:'Refuse the sale and tell the smith to hold it',result:'The stranger leaves without the axle; the smith calls the county office.'}], aftermathTitle:'The Axle Goes Back', aftermath:'The public-works axle is returned to its crew. The wagon is moved only after the smith checks its own damaged part; no stolen component becomes a reward.', endings:[{id:'helpUnload',label:'Help the crew unload and move the stranded wagon',result:'The cargo reaches the roadside store while the wheel waits for repair.'},{id:'giveStatement',label:'Give the smith a witness account and leave',result:'The axle remains in the smith’s custody until the county crew collects it.'}], rewardText:'The foreman pays the agreed three-coin road-work fee; the axle remains public property.', gear:'foldingCarriageJack',gearName:'Folding Carriage Jack',provenance:'This outcome is coin-only; the jack is not transferred because the stolen axle and public tools remain with their owners.', coins:3, lesson:'A serial mark and inventory record can distinguish abandoned equipment from stolen public property.' },
  { id:'the-rain-on-the-waybill', title:'The Rain on the Waybill', subtitle:'A freight wagon is stopped in a storm while two riders argue over a sealed document case.', risk:'MODERATE', setting:'railroad road crossing', activity:'investigation/mystery', hook:'A storm-side robbery is resolved by checking document custody and cargo seals.', startTitle:'The Wet Waybill', start:'Rain drives a freight wagon under the rail bridge. The waybill case is missing, but the cargo seal is unbroken. Two riders approach from opposite ends of the bridge; one says the other took the papers, and both carry matching railway coats.', approaches:[{id:'checkSeal',label:'Check the cargo seal before hearing either claim',result:'The numbered seal is intact and matches the station copy.'},{id:'shelterDriver',label:'Get the driver under the bridge before questioning',result:'The driver is dry and unhurt; both riders keep their distance.'},{id:'askStation',label:'Signal the station clerk to bring the duplicate waybill',result:'The clerk answers with a lamp but says it will take time to reach the bridge.'}], threatTitle:'Only One Coat Is Issued', threat:'The station clerk arrives and confirms that one coat was stolen last week. The rider wearing it reaches for the wet waybill case; the other backs toward the open track.', responses:[{id:'keepCaseDry',label:'Move the case beneath the bridge and away from the track',result:'The case stays dry while the clerk checks the coat’s issue number.'},{id:'askNumber',label:'Ask each rider to name the station issue number',result:'The false worker gives a number from a different division and leaves.'},{id:'standWithDriver',label:'Stand beside the driver until the clerk identifies the worker',result:'The driver remains behind the wagon; the false worker retreats without the case.'}], aftermathTitle:'The Waybill Is Recovered', aftermath:'The legitimate clerk recovers the case and verifies the seal. No cargo is missing; the false worker’s identity remains uncertain, but their borrowed coat is returned to the station.', endings:[{id:'carryCase',label:'Carry the sealed case to the station office',result:'The clerk signs it in without opening the cargo.'},{id:'waitBridge',label:'Wait with the driver for the station wagon',result:'The freight remains sheltered until a proper replacement coat arrives.'}], rewardText:'The stationmaster transfers a spare Lockable Map Case from the records room as thanks for keeping the waybill intact.', gear:'lockableMapCase',gearName:'Lockable Map Case',provenance:'The stationmaster releases a duplicate case after documenting the recovered original; no railway record is taken.', coins:2, lesson:'A familiar uniform is not proof of employment; check its issue mark and the cargo seal.', combat:{enemy:'freight impersonator',winChance:.47,damage:4,win:'The false worker retreats when the station clerk names the wrong issue number.',loss:'You are shoved against the wagon, but the clerk gets the case and the driver clear.'} },
  { id:'the-cold-iron-latch', title:'The Cold Latch', subtitle:'A roadside shed is open and a family’s winter tools are missing.', risk:'LOW', setting:'farm lane and tool shed', activity:'investigation/mystery', hook:'The traveler helps recover borrowed tools without assuming every missing item was stolen.', startTitle:'An Open Shed Door', start:'A farm family finds its tool shed open after market day. Two spades and a coil of rope are missing; the latch is intact. A hired hand says a neighbor borrowed them, while the family says no one asked.', approaches:[{id:'checkWorkNotes',label:'Check the family’s work notes for a loan entry',result:'A note records one spade loaned last week, but not the second.'},{id:'followRope',label:'Look for the rope’s distinctive red whipping',result:'A red thread is caught on the fence toward the mill road.'},{id:'askNeighbor',label:'Ask the neighbor before searching their yard',result:'The neighbor says the tools were left by the public well after work.'}], threatTitle:'The Tools at the Well', threat:'The tools are beside the well, but a stranger is packing them into a cart. They say the family sold them; the neighbor says the cart belongs to the mill.', responses:[{id:'compareMarks',label:'Compare the tool marks with the family inventory',result:'The spade handles carry the family’s burned initials.'},{id:'askMill',label:'Ask the miller to identify the cart',result:'The miller confirms the cart is his, but did not authorize anyone to take tools.'},{id:'callFamily',label:'Call the family to witness the recovery',result:'The family identifies both spades and the rope; the stranger leaves the cart.'}], aftermathTitle:'A Loan Recorded', aftermath:'The neighbor admits borrowing one spade with permission and leaving it by the well. The second spade and rope were taken by the stranger; they are returned to the family.', endings:[{id:'recordLoan',label:'Write down the loan before returning the first spade',result:'The neighbor signs for the borrowed tool and the family updates its shed list.'},{id:'walkToolsHome',label:'Carry the recovered tools back to the farm',result:'The family receives its property and decides whether to report the stranger.'}], rewardText:'The family pays one coin for the return and gives you a separate Cold-Iron Nail pouch they no longer need for the shed latch.', gear:'coldIronNails',gearName:'Cold-Iron Nails',provenance:'The family transfers a separate unused supply pouch after confirming it is not among the missing tools.', coins:1, lesson:'A tool can be borrowed, misplaced, or stolen; compare the account with ownership marks.', lore:'The public well was built where two farm lanes met before the mill road was laid.' },
  { id:'the-forked-shadow', title:'The Forked Shadow', subtitle:'A lone rider keeps matching your turns without closing the distance.', risk:'MODERATE', setting:'open country road', activity:'travel/exploration', hook:'A pursuit is met with route choice and observation, not an automatic duel.', startTitle:'The Same Rider Again', start:'A rider has appeared behind you at three successive forks. They remain far enough away that you cannot identify their face. The road ahead divides between an open toll station and a narrow wooded lane.', approaches:[{id:'openRoad',label:'Take the open road toward the station',result:'The rider keeps distance and does not enter the busy stretch.'},{id:'askAtFarm',label:'Stop at the farm gate and ask for a witness',result:'The rider waits beyond the gate while the farmer watches from the porch.'},{id:'changePace',label:'Vary your pace and watch whether they follow',result:'The rider matches your slower pace but does not pass.'}], threatTitle:'A Message, Not a Shot', threat:'At the station the rider dismounts and says they were sent to return a purse you left at the last inn. They have no receipt, and the purse may belong to another traveler. The station clerk is present.', responses:[{id:'askClerk',label:'Ask the clerk to record the purse before opening it',result:'The clerk notes the purse’s condition and asks for an owner description.'},{id:'askOwnerDetails',label:'Ask the rider where the purse was found',result:'The rider names the inn and describes a stitched initials patch.'},{id:'declinePurse',label:'Decline the purse until its owner is found',result:'The rider leaves it with the clerk and rides away.'}], aftermathTitle:'A Purse with Initials', aftermath:'The inn confirms the initials belong to a guest who left that morning. The rider was paid to follow you after mistaking you for the guest, but did not threaten you.', endings:[{id:'sendPurse',label:'Send the purse to the inn by station courier',result:'The owner can claim it against the inn register.'},{id:'leaveRecord',label:'Leave your account with the clerk',result:'The mistaken pursuit is recorded without accusing the rider of a robbery.'}], rewardText:'The station clerk pays the agreed two-coin witness fee; no purse or property is kept.', gear:'roadsideSignalMirror',gearName:'Roadside Signal Mirror',provenance:'This is a coin-only witness route. The mirror stays with the station clerk and is not awarded.', coins:2, lesson:'Repeated presence can be a warning, but the reason becomes clearer when a safe witness is available.' },
  { id:'the-axle-grease-mark', title:'The Grease Mark', subtitle:'A wagon wheel loosens on a lonely stretch where a roadside crew has been working.', risk:'HIGH', setting:'county road and wagon turnout', activity:'labor/repair', hook:'A sabotaged fitting is checked before travel resumes; an attack is conditional and avoidable.', startTitle:'A Wheel That Wobbles', start:'A farmer’s wagon begins to wobble at a turnout. The wheel nuts are loose, but grease marks cross the wrench flats. A road crew left a tool board nearby; two workers are visible farther down the route.', approaches:[{id:'stopWagon',label:'Stop the wagon on level ground',result:'The wheel settles before it can come free; the driver is shaken but unhurt.'},{id:'checkToolBoard',label:'Check which tools remain on the crew board',result:'A Compact Wheel Wrench is missing from the board and the crew’s sign-out slate is blank.'},{id:'signalWorkers',label:'Signal the road crew before touching the wheel',result:'The workers answer and close the road behind the wagon.'}], threatTitle:'A Man Comes Back for the Wrench', threat:'A stranger steps from the ditch and says the wrench is his. The road crew identifies it as theirs; he has a second wrench tucked in his belt and glances toward the open field.', responses:[{id:'askReturn',label:'Ask him to put the crew wrench on the ground',result:'He drops it and walks away when the workers approach.'},{id:'protectDriver',label:'Move the driver behind the wagon and call the crew',result:'The driver reaches cover and the stranger leaves before anyone closes in.'},{id:'checkWheel',label:'Tighten the wheel only after the stranger leaves',result:'The crew checks each nut with its own tool before the wagon moves.'}], aftermathTitle:'A Wheel Held on the Road', aftermath:'The wheel was deliberately loosened, but the driver cannot identify who did it. The road crew recovers its wrench and checks the other passing wagons.', endings:[{id:'walkToFarm',label:'Walk the wagon to the farm before traveling again',result:'The driver has the wheel and axle examined under shelter.'},{id:'escortSlowly',label:'Escort the wagon to the staffed road station',result:'The station closes the turnout until the crew checks for further tampering.'}], rewardText:'The road foreman releases an older Carriage Jack from the crew’s retired equipment and records the transfer.', gear:'foldingCarriageJack',gearName:'Folding Carriage Jack',provenance:'The public crew signs out a retired jack to you after the active wheel is checked and the tool is formally removed from inventory.', coins:2, lesson:'Grease and tool marks can suggest recent work, but they do not identify who loosened a fitting.', combat:{enemy:'wheel saboteur',winChance:.49,damage:5,win:'The stranger leaves the crew wrench and retreats across the field when workers answer.',loss:'You are struck beside the wagon, but the driver and workers reach the road station.'} },
];

// These three quiet investigations are intentionally coin-forward. They do
// not transfer the item named by their story evidence; keeping them out of
// the Gear menu prevents a visible offer from contradicting the ownership
// resolution in the scene.
for (const id of ['the-courier-who-came-back', 'the-blue-thread', 'the-forked-shadow']) {
  const story = stories.find((candidate) => candidate.id === id);
  if (story) {
    story.gear = undefined;
    story.gearName = undefined;
    story.provenance = undefined;
  }
}

// Optional carried-Gear approaches grant information or safer positioning;
// none is required to complete the encounter.
const ownedGearCallbacks: Array<{ story: string; stage: 'approaches' | 'responses'; choice: string; item: string; label: string; result: string }> = [
  { story: 'the-second-rope', stage: 'approaches', choice: 'steadyHorses', item: 'travelRope', label: 'Use your Travel Rope to secure the horses on the downhill side', result: 'Your rope gives the horses a safe tie point; you notice the original lead was cut and retied around a tree.' },
  { story: 'the-rain-on-the-waybill', stage: 'approaches', choice: 'checkSeal', item: 'lockableMapCase', label: 'Keep the wet waybill in your Lockable Map Case while checking its seal', result: 'The case keeps the paper legible; its county stamp is intact, though a corner was deliberately lifted.' },
  { story: 'the-axle-grease-mark', stage: 'approaches', choice: 'checkToolBoard', item: 'compactWheelWrench', label: 'Compare the wrench marks with your Compact Wheel Wrench', result: 'Your wrench fits the wheel nuts, but the grease across their flats suggests someone loosened them with a different tool.' },
];
for (const callback of ownedGearCallbacks) {
  const story = stories.find((candidate) => candidate.id === callback.story);
  const choice = story?.[callback.stage].find((candidate) => candidate.id === callback.choice);
  if (choice) Object.assign(choice, { requiresItem: callback.item, label: callback.label, result: callback.result });
}

function build(c: RoadStory): Scenario {
  const rewardClass = c.gear ? inventoryClass(c.gear) : undefined;
  const ownedRewardChoice = c.gear && c.gearName ? {
    id: 'acceptGear', label: `Accept ${c.gearName}`,
    requirements: rewardClass === 'SUPPLY' ? { canAddSupplies: { [c.gear]: 1 } } : { notOwnedItems: [c.gear] },
    next: 'gear',
    effects: rewardClass === 'SUPPLY' ? { gainSupplies: { [c.gear]: 1 }, historyFlags: [`earned_${c.id}_gear`] } : { gainItems: [c.gear], historyFlags: [`earned_${c.id}_gear`] },
  } : undefined;
  const approachChoices: Scene['choices'] = c.approaches.map((choice) => ({ id: `approach_${choice.id}`, label: choice.label, ...(choice.requiresItem ? { requirements: { items: [choice.requiresItem] } } : {}), next: 'threat', effects: { setFlags: [`road_approach_${choice.id}`] } }));
  const responseChoices: Scene['choices'] = [
    ...c.responses.map((choice) => ({ id: `respond_${choice.id}`, label: choice.label, ...(choice.requiresItem ? { requirements: { items: [choice.requiresItem] } } : {}), next: 'aftermath', effects: { setFlags: [`road_response_${choice.id}`] } })),
    ...(c.combat ? [{ id: 'fight', label: `Fight ${c.combat.enemy}`, hint: 'They have shown a weapon or made a direct threat; the open route remains available if you withdraw.', effects: { combat: { enemy: c.combat.enemy, winChance: c.combat.winChance, damageOnWin: 1, damageOnLoss: c.combat.damage, winNext: 'fightWon', lossNext: 'fightLost' } } }] : []),
  ];
  const scenes: Record<string, Scene> = {
    approach: s('approach', c.startTitle, c.start, approachChoices),
    threat: s('threat', c.threatTitle, c.threat, responseChoices, c.risk === 'HIGH' || c.risk === 'SEVERE' ? 'warning' : 'safe', c.approaches.map((choice) => ({ requirements: { flags: [`road_approach_${choice.id}`] }, text: choice.result }))),
    aftermath: s('aftermath', c.aftermathTitle, c.aftermath, c.endings.map((choice) => ({ id: `ending_${choice.id}`, label: choice.label, next: 'settlement', effects: { setFlags: [`road_ending_${choice.id}`] } })), 'safe', c.responses.map((choice) => ({ requirements: { flags: [`road_response_${choice.id}`] }, text: `${choice.result} ${c.aftermath}` }))),
    settlement: s('settlement', 'The Road Opens', c.rewardText, [
      ...(ownedRewardChoice ? [ownedRewardChoice] : []),
      { id: 'takeCoins', label: `Take ${c.coins} coins instead`, next: 'coins', effects: { money: c.coins } },
      { id: 'keepLesson', label: 'Decline payment and keep the practical lesson', next: 'lesson', effects: { knowledge: [c.lesson] } },
      { id: 'decline', label: 'Decline all compensation and leave', next: 'unpaid' },
    ], 'safe', c.endings.map((choice) => ({ requirements: { flags: [`road_ending_${choice.id}`] }, text: `${choice.result} ${c.rewardText}` }))),
    ...(c.gear && c.gearName ? { gear: e('gear', rewardClass === 'SUPPLY' ? 'A New Owner for the Supply' : 'A New Owner for the Gear', c.provenance ?? '') } : {}),
    coins: e('coins', 'The Agreed Payment', `You take ${c.coins} coins${c.gearName ? ` instead of the ${c.gearName}` : ''}. ${c.rewardText}`),
    lesson: e('lesson', 'A Lesson from the Road', `You leave without money${c.gearName ? ` or the ${c.gearName}` : ''}. ${c.lesson}`),
    unpaid: e('unpaid', 'The Road behind You', 'You decline compensation. The road is open or safely avoided, and nothing changes ownership.'),
  };
  if (c.combat) {
    scenes.fightWon = s('fightWon', 'The Threat Breaks', c.combat.win, [{ id: 'checkRoad', label: 'Check the people and the road before continuing', next: 'aftermath', effects: { setFlags: ['road_combat_won'] } }], 'warning');
    scenes.fightLost = e('fightLost', 'A Costly Withdrawal', c.combat.loss);
  }
  const tags = largeTags({ hook: c.hook, activity: c.activity, role: 'traveler/passenger', tone: 'tense/dangerous', risk: c.risk, setting: c.setting, fantasy: 'NONE', combat: c.combat ? 'POSSIBLE' : 'NONE', structures: ['branching narrative', 'evidence review', 'retreat route', 'consequence and restitution'], entry: ['witnesses incident'], rewards: ['Gear', 'coins', 'reusable Knowledge', ...(c.lore ? ['Lore'] : [])], outcomes: ['success/partial success', 'escape/survival', 'walk-away/refusal', 'negotiated compromise'] });
  return largeAdventure(c.id, c.title, c.subtitle, tags, 'approach', scenes);
}

export const ROAD_DANGER_GENRE_BATCH: Scenario[] = stories.map(build);
